import * as React from "react";
import { useEffect, useMemo, useState } from "react";
import { SPHttpClient } from "@microsoft/sp-http";
import styles from "../styles/OurPortfolio.module.scss";
import { IOurPortfolioProps } from "./IOurPortfolioProps";

/** List item shape */
type CmsItem = {
  Id: number;
  Title: string;          // Brand name (main rows) OR sub-brand name (child rows)
  SortOrder?: number;     // only meaningful on main brand rows
  IconUrl?: any;          // Image column JSON or hyperlink picture string
  SubCols?: number;       // only meaningful on main brand rows
  BrandChoice?: string | null; // the Choice field value on sub-brand rows
};

/** Normalize Image/Hyperlink column to src URL */
const imgSrc = (img: any): string | null => {
  if (!img) return null;
  if (typeof img === "string") return img;
  return img.Url || img.serverRelativeUrl || null;
};

const OurPortfolio: React.FC<IOurPortfolioProps> = (props) => {
  const listTitle  = props.listTitle  || "AboutDHREOurPortfolio";
  const brandField = props.brandField || "ABoutDHRECategory"; // Choice column internal name

  const [items, setItems]       = useState<CmsItem[]>([]);
  const [loading, setLoading]   = useState(true);
  const [error, setError]       = useState<string | null>(null);

  /** fetch once */
  useEffect(() => {
    (async () => {
      try {
        setLoading(true);

        // include the choice column (brandField) in $select
        const url =
          `${props.siteUrl}/_api/web/lists/getbytitle('${encodeURIComponent(listTitle)}')/items` +
          `?$select=Id,Title,SortOrder,IconUrl,SubCols,${brandField}`;

        const res = await props.spfxContext.spHttpClient.get(url, SPHttpClient.configurations.v1);
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const json = await res.json();

        const data: CmsItem[] = (json?.value || []).map((r: any) => ({
          Id: r.Id,
          Title: r.Title,
          SortOrder: r.SortOrder ?? r.Sortorder ?? r.sortOrder,
          IconUrl:  r.IconUrl,
          SubCols: (typeof r.SubCols === "number" ? r.SubCols : undefined),
          BrandChoice: (typeof r[brandField] === "string" ? r[brandField] : null)
        }));

        setItems(data);
      } catch (e: any) {
        setError(e?.message || "Failed to load items");
      } finally {
        setLoading(false);
      }
    })();
  }, [props.siteUrl, props.spfxContext, listTitle, brandField]);

  /** main brands = rows with NO BrandChoice */
  const mainBrands = useMemo(() => {
    const base = items.filter(i => !i.BrandChoice);
    return base
      .sort((a, b) => (a.SortOrder ?? 99999) - (b.SortOrder ?? 99999) || a.Title.localeCompare(b.Title))
      .slice(0, 4);
  }, [items]);

  /** group sub-brands by BrandChoice */
  const subByBrand = useMemo(() => {
    const map = new Map<string, CmsItem[]>();
    for (const it of items) {
      if (it.BrandChoice) {
        const key = it.BrandChoice.trim();
        const arr = map.get(key) || [];
        arr.push(it);
        map.set(key, arr);
      }
    }
    map.forEach((arr: CmsItem[], key: string) => {
      arr.sort(
        (a: CmsItem, b: CmsItem) =>
          a.Title.localeCompare(b.Title) || a.Id - b.Id
      );
      map.set(key, arr);
    });
    return map;
  }, [items]);

  if (loading) return <section className={styles.wrapper}>Loading…</section>;
  if (error)   return <section className={styles.wrapper}>Error: {error}</section>;
  if (!mainBrands.length) return <section className={styles.wrapper}>No brands configured.</section>;

  return (
    <section className={styles.wrapper} aria-labelledby="portfolioHeading">
      {/* Title */}
      <h2 id="portfolioHeading" className={styles.heading}>
        <span className={styles.our}>Our</span>{" "}
        <span className={styles.portfolio}>Portfolio</span>
      </h2>

      {/* Four columns (card + always-visible sub-grid) */}
      <div className={styles.brandsColumns}>
        {mainBrands.map((brand) => {
          const brandName = brand.Title.trim();
          const logo = imgSrc(brand.IconUrl);
          const cols = brand.SubCols === 3 ? 3 : 2; // Nakheel=3, others=2 by list

          return (
            <div className={styles.brandColumn} key={brand.Id}>
              <div className={styles.brandCard} title={brandName}>
                {logo ? (
                  <img className={styles.brandLogo} src={logo} alt={brandName} />
                ) : (
                  <span className={styles.brandFallback}>{brandName}</span>
                )}
              </div>

              {/* sub-brands for this brand (using Choice) */}
              <div className={cols === 3 ? styles.subGridCols3 : styles.subGridCols2}>
                {(subByBrand.get(brandName) || []).map((sb) => {
                  const subName = sb.Title.trim();
                  const sbLogo = imgSrc(sb.IconUrl);
                  return (
                    <div className={styles.subCell} key={sb.Id} title={subName}>
                      {sbLogo ? (
                        <img className={styles.subLogo} src={sbLogo} alt={subName} />
                      ) : (
                        <span className={styles.subFallback}>{subName}</span>
                      )}
                    </div>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
    </section>
  );
};

export default OurPortfolio;
